import{NATURE_SOUNDS,NATURE_MAX_VOLUME,NATURE_DEFAULT_VOLUME,createQuranNatureAudio}from './quran-nature-audio.js';
import{read,write}from './storage.js';
export function mountQuranPlayerExtras(panel,{playback,ruqyah,createNature=createQuranNatureAudio,doc=document,win=window}={}){
 const root=doc.createElement('section');root.className='quran-player-extras';root.setAttribute('aria-label','Таймер и фон чтения');
 const clock='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6"/></svg>',drop='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3C8 9 5 11 5 15a7 7 0 0 0 14 0c0-4-3-6-7-12ZM9 16a3 3 0 0 0 3 3"/></svg>';
 root.innerHTML='<div class="quran-extras-actions"><button type="button" data-extra="timer" aria-expanded="false" aria-controls="quran-sleep-options">'+clock+'<span data-timer-label>Таймер</span></button><button type="button" data-extra="nature" aria-expanded="false" aria-controls="quran-nature-options">'+drop+'<span>Фон природы</span></button></div><fieldset id="quran-sleep-options" hidden><legend>Остановить чтение</legend><div class="quran-extra-choices">'+[[15,'15 мин'],[30,'30 мин'],[45,'45 мин'],[60,'60 мин'],['end','До конца суры'],['off','Выключен']].map(([value,title])=>'<button type="button" data-sleep="'+value+'" aria-pressed="false">'+title+'</button>').join('')+'</div><p class="quran-extra-note">Таймер продолжает отсчёт во время паузы.</p></fieldset><fieldset id="quran-nature-options" hidden><legend>Баланс фона с чтением</legend><div class="quran-extra-choices"><button type="button" data-nature="off" aria-pressed="true">Выключен</button>'+NATURE_SOUNDS.map(sound=>'<button type="button" data-nature="'+sound.id+'" aria-pressed="false">'+sound.name+'</button>').join('')+'</div><div class="quran-extra-choices quran-nature-presets" aria-label="Быстрый выбор громкости фона"><button type="button" data-nature-level="25" aria-pressed="false">Тихо</button><button type="button" data-nature-level="50" aria-pressed="false">Средне</button><button type="button" data-nature-level="75" aria-pressed="false">Громче</button></div><label class="quran-nature-volume">Громкость фона <output data-nature-volume></output><input type="range" min="0" max="'+NATURE_MAX_VOLUME+'" step="1" aria-label="Громкость фона природы"></label><p class="quran-extra-note">Общая громкость — кнопками телефона, баланс фона — этим ползунком.</p><p class="quran-extra-note" data-nature-status role="status"></p></fieldset>';
 panel.append(root);let disposed=false,lastStopped=true;
 const nature=createNature({volume:read('quran-nature-volume',NATURE_DEFAULT_VOLUME)}),volume=root.querySelector('input');volume.value=String(nature.state.volume);
 function drawTimer(){const timer=playback.state.sleepTimer||{mode:null};root.querySelector('[data-timer-label]').textContent=timer.mode==='end'?'До конца суры':timer.mode?Math.floor(timer.remaining/60)+':'+String(timer.remaining%60).padStart(2,'0'):'Таймер';for(const button of root.querySelectorAll('[data-sleep]'))button.setAttribute('aria-pressed',String(button.dataset.sleep===(timer.mode===null?'off':String(timer.mode))));}
 function sync(){if(disposed)return;const state=playback.state;root.hidden=!!ruqyah.state.record;drawTimer();const stopped=!state.surah||state.status==='stopped',clear=stopped&&!lastStopped;lastStopped=stopped;if(clear)void nature.select(null);void nature.sync(!ruqyah.state.record&&state.status==='playing');}
 const offNature=nature.subscribe(state=>{volume.value=String(state.volume);for(const preset of root.querySelectorAll('[data-nature-level]'))preset.setAttribute('aria-pressed',String(Number(preset.dataset.natureLevel)===state.volume));for(const button of root.querySelectorAll('[data-nature]'))button.setAttribute('aria-pressed',String(button.dataset.nature===(state.kind||'off')));root.querySelector('[data-nature-volume]').textContent=state.volume+'%';root.querySelector('[data-nature-status]').textContent=!state.supported?'Фон недоступен в этом браузере.':state.error?'Не удалось включить фон. Нажмите на звук ещё раз.':state.systemPaused?'Телефон приостановил фон. Нажмите на выбранный звук, чтобы включить его снова.':state.kind?state.playing?'Фон звучит вместе с чтением.':'Фон включится вместе с чтением.':'Выберите звук и настройте его громкость относительно чтения.';});
 root.onclick=event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.extra){const area=root.querySelector(button.dataset.extra==='timer'?'#quran-sleep-options':'#quran-nature-options'),opening=area.hidden;for(const field of root.querySelectorAll('fieldset'))field.hidden=true;for(const toggle of root.querySelectorAll('[data-extra]'))toggle.setAttribute('aria-expanded','false');area.hidden=!opening;button.setAttribute('aria-expanded',String(opening));}else if(button.dataset.sleep){const value=button.dataset.sleep;playback.setSleepTimer(value==='off'?null:value==='end'?'end':Number(value));drawTimer();}else if(button.dataset.natureLevel){const value=Number(button.dataset.natureLevel);void nature.setVolume(value);write('quran-nature-volume',value);}else if(button.dataset.nature){void nature.select(button.dataset.nature==='off'?null:button.dataset.nature);}};
 volume.oninput=()=>void nature.setVolume(Number(volume.value));volume.onchange=()=>{write('quran-nature-volume',Number(volume.value));};
 const gesture=event=>{if(event.isTrusted&&nature.state.kind&&event.target.closest('[data-toggle]'))void nature.unlock();},resume=()=>{playback.checkSleepTimer();if(!doc.hidden&&nature.state.kind&&playback.state.status==='playing')void nature.unlock();};
 panel.addEventListener('pointerdown',gesture,{capture:true,passive:true});doc.addEventListener('visibilitychange',resume);win.addEventListener('pageshow',resume);win.addEventListener('focus',resume);
 const off=playback.subscribe(sync),offRuqyah=ruqyah.subscribe(sync),offTimer=playback.subscribeSleepTimer?.(drawTimer)||(()=>{});
 return()=>{disposed=true;off();offRuqyah();offTimer();offNature();nature.destroy();panel.removeEventListener('pointerdown',gesture,true);doc.removeEventListener('visibilitychange',resume);win.removeEventListener('pageshow',resume);win.removeEventListener('focus',resume);root.remove();};
}
